import { describe, expect, it } from "vitest";
import { buildJmaEarlyForecastTileUrl } from "./earlyForecastTileUrl";

describe("buildJmaEarlyForecastTileUrl", () => {
  it("uses the target frame member in a rasrf tile URL", () => {
    expect(buildJmaEarlyForecastTileUrl(
      { basetime: "20260924130000", validtime: "20260924150000", member: "immed" },
      10,
      909,
      403,
    )).toBe(
      "https://www.jma.go.jp/bosai/jmatile/data/rasrf/20260924130000/immed/20260924150000/surf/rasrf/10/909/403.png",
    );
  });

  it("keeps none when the target frame member is none", () => {
    expect(buildJmaEarlyForecastTileUrl(
      { basetime: "20260924130000", validtime: "20260924150000", member: "none" },
      10,
      909,
      403,
    )).toBe(
      "https://www.jma.go.jp/bosai/jmatile/data/rasrf/20260924130000/none/20260924150000/surf/rasrf/10/909/403.png",
    );
  });
});

import type { JmaEarlyForecastTargetTime } from "./earlyForecastTargetTimes";

export function buildJmaEarlyForecastTileUrl(
  frame: Pick<JmaEarlyForecastTargetTime, "basetime" | "validtime" | "member">,
  zoom: number,
  tileX: number,
  tileY: number,
): string {
  return [
    "https://www.jma.go.jp/bosai/jmatile/data/rasrf",
    frame.basetime,
    frame.member,
    frame.validtime,
    "surf",
    "rasrf",
    String(zoom),
    String(tileX),
    `${tileY}.png`,
  ].join("/");
}
